import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionMeasureInput } from 'claude-code'

import type { Breakdown, Git, Scan, Snapshot } from '../types'
import { fromEngine, fromEstimate, parseShortstat, scanChunk } from './meter'
import type { EngineRow } from './meter'
import { Band, Pane } from './view'

export { cells, estimateSplit, filled, fromEngine, fromEstimate, percentOf, scanChunk, share, splitMessages, until } from './meter'

const PANE = 'usage-meter'
const TITLE = 'Usage'
const POLL_MS = 60_000
// One read of the transcript takes at most this many bytes (under $.process.run's 4 MiB cap).
const CHUNK = 4_000_000
const CHUNKS_PER_REFRESH = 8

const snapAtom = atom({ plugin: 'usage-meter', key: 'snap' } as const, null)
const gitAtom = atom({ plugin: 'usage-meter', key: 'git' } as const, null)
const breakdownAtom = atom({ plugin: 'usage-meter', key: 'breakdown' } as const, null)
const scanAtom = atom({ plugin: 'usage-meter', key: 'scan' } as const, null)
const transcriptAtom = atom({ plugin: 'usage-meter', key: 'transcript' } as const, null)

type $ = EngineInterface

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const ran = await next(e)
    await $.command.register({
      name: 'usage-meter',
      description: 'Open the usage pane: plan limits, cost and the context breakdown',
    })
    await refresh($)
    try {
      $.clock.every(POLL_MS, () => void refresh($))
    } catch {
      // No timers here (a test host): figures still refresh when a turn ends.
    }
    return ran
  })

  // The engine pushes its own figures after each main-thread turn and when a plan window moves.
  on('session.measure', async ($, e, next) => {
    await writeSnap($, e)
    return next(e)
  })

  // A turn ended: git and the breakdown move too. Done on a timer so the turn's end is not held.
  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (e.agentId === undefined) {
      try {
        $.clock.after(0, () => void refresh($))
      } catch {
        await refresh($)
      }
    }
    return done
  })

  // The transcript's path, from the classic hooks' envelope.
  on('classic.SessionStart', async ($, e, next) => (await notePath($, e.transcript_path), next(e))).catch(($, e, next) => next(e))
  on('classic.UserPromptSubmit', async ($, e, next) => (await notePath($, e.transcript_path), next(e))).catch(($, e, next) => next(e))
  on('classic.Stop', async ($, e, next) => (await notePath($, e.transcript_path), next(e))).catch(($, e, next) => next(e))

  // Claude Code ships /usage, so the name cannot be registered: answer the built-in instead.
  // `/usage builtin` still runs Claude Code's own; if this hook fails, the built-in runs.
  on('command.run', { command: 'usage' }, async ($, e, next) => {
    if (e.args.trim() === 'builtin') return next({ ...e, args: '' })
    await openPane($)
    return { text: 'Usage pane opened. `/usage builtin` runs Claude Code\'s own /usage.' }
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'usage-meter' }, async $ => {
    await openPane($)
    return { text: 'Usage pane opened.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const data = await gather($, e.props.bodyColumns)
    if (data.snap === null) return next(e)
    return Band({ Box, Text, Button }, data, () => void openPane($))
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    return Pane({ Box, Text, Button }, await gather($, e.props.bodyColumns), () => void refresh($))
  })
}

let running: Promise<void> | null = null
let again = false

/** One refresh at a time; a call that lands mid-refresh runs one more after it. */
function refresh($: $): Promise<void> {
  if (running) {
    again = true
    return running
  }
  running = (async () => {
    do {
      again = false
      await Promise.all([refreshSnap($), refreshGit($)]).catch(() => undefined)
      await refreshBreakdown($).catch(() => undefined)
    } while (again)
  })().finally(() => {
    running = null
  })
  return running
}

async function openPane($: $) {
  const opened = await $.ui.open({ id: PANE, title: TITLE })
  void refresh($)
  return opened
}

/** The transcript's path, from the classic hooks' envelope (each fires with or without a settings hook). */
async function notePath($: $, path: string | undefined) {
  if (path && path !== (await read($, transcriptAtom))) await update($, transcriptAtom, () => path)
}

async function gather($: $, columns: number) {
  return {
    snap: await read($, snapAtom),
    git: await read($, gitAtom),
    breakdown: await read($, breakdownAtom),
    now: await $.clock.now(),
    columns,
  }
}

async function refreshSnap($: $) {
  await writeSnap($, await $.session.usage())
}

/** The engine's figures, as they are: a figure it has not got stays absent (limits empty, cost null). */
async function writeSnap($: $, u: Pick<SessionMeasureInput, 'context' | 'rateLimits' | 'cost'> & { startedAt?: number }) {
  const model = await $.session.model()
  const startedAt = u.startedAt ?? (await read($, snapAtom))?.startedAt ?? (await $.session.usage()).startedAt
  const snap: Snapshot = {
    model,
    window: u.context.window,
    limits: u.rateLimits.map(l => ({ kind: l.kind, percentUsed: l.percentUsed, ...(l.resetsAt ? { resetsAt: l.resetsAt } : {}) })),
    costUsd: u.cost ? u.cost.usd : null,
    startedAt,
    measuredAt: await $.clock.now(),
    ...(u.context.tokens !== undefined ? { tokens: u.context.tokens } : {}),
    ...(u.context.percent !== undefined ? { percent: u.context.percent } : {}),
  }
  await update($, snapAtom, () => snap)
}

async function refreshGit($: $) {
  const repo = await $.session.repo()
  if (repo === null) {
    await update($, gitAtom, () => null)
    return
  }
  const [head, diff] = await Promise.all([
    $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD', '--show-toplevel'], { timeoutMs: 5000 }),
    $.process.run(['git', 'diff', 'HEAD', '--shortstat'], { timeoutMs: 5000 }),
  ])
  const [branch = '', top = ''] = head.stdout.trim().split('\n')
  if (head.exitCode !== 0 || !branch) return
  // The engine's repo root is the main working tree's; a different top level is a linked worktree.
  const worktree = top && top !== repo.root ? (top.split('/').pop() ?? null) : null
  const git: Git = { branch: branch === 'HEAD' ? 'detached' : branch, worktree, ...parseShortstat(diff.stdout) }
  await update($, gitAtom, () => git)
}

async function refreshBreakdown($: $) {
  const counts = await scanTranscript($)
  const usage = await $.session.usage({ breakdown: 'summary' })
  const b = usage.context.breakdown
  let next: Breakdown | null
  if (b && b.categories.length) {
    const rows: EngineRow[] = b.categories.map(c => ({ name: c.name, tokens: c.tokens, color: c.color, kind: c.kind }))
    next = fromEngine(rows, counts, b.rawMaxTokens, b.isAutoCompactEnabled ? (b.autoCompactThreshold ?? null) : null)
  } else if (usage.context.tokens) {
    next = fromEstimate(counts, usage.context.tokens, usage.context.window)
  } else {
    next = null
  }
  await update($, breakdownAtom, () => next)
}

/** Where the transcript is: the classic hooks' envelope, else the engine's projects folder by session id. */
async function transcriptPath($: $): Promise<string | null> {
  const known = await read($, transcriptAtom)
  if (known) return known
  const home = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${(await $.env.get('HOME')) ?? ''}/.claude`
  const slug = (await $.session.root()).replace(/[^a-zA-Z0-9]/g, '-')
  const guess = `${home}/projects/${slug}/${await $.session.id()}.jsonl`
  return (await $.fs.exists(guess)) ? guess : null
}

/**
 * Characters per kind since the last compaction. Read only from where the last read stopped, and not
 * at all when the file's size has not changed: usage_bars.py's cache, kept in the session's state.
 */
async function scanTranscript($: $): Promise<Record<string, number>> {
  const path = await transcriptPath($)
  if (!path) return {}
  const prev = await read($, scanAtom)
  let size: number
  try {
    size = (await $.fs.stat(path)).size
  } catch {
    return prev?.counts ?? {}
  }
  const base: Scan = prev && prev.path === path && prev.offset <= size ? prev : { path, offset: 0, counts: {} }
  if (base.offset === size) return base.counts

  const counts = { ...base.counts }
  let offset = base.offset
  for (let i = 0; i < CHUNKS_PER_REFRESH && offset < size; i++) {
    const r = await $.process.run(['/bin/sh', '-c', 'tail -c +"$1" "$2" | head -c "$3"', 'sh', String(offset + 1), path, String(CHUNK)], {
      timeoutMs: 10_000,
    })
    if (r.exitCode !== 0) break
    const n = scanChunk(r.stdout, counts)
    if (n > 0) {
      offset += n
      continue
    }
    // A single line longer than a chunk: step over it uncounted, or wait if it is still being written.
    if (r.stdout.length < CHUNK - 4) break
    const w = await $.process.run(['/bin/sh', '-c', 'tail -c +"$1" "$2" | head -n 1 | wc -c', 'sh', String(offset + 1), path])
    const skip = Number(w.stdout.trim())
    if (!skip) break
    offset += skip
  }
  const scan: Scan = { path, offset, counts }
  await update($, scanAtom, () => scan)
  return counts
}

