// The sums behind the meter: a port of ~/.claude/statusline/usage_bars.py (classify, measure,
// segments, until), plus the step that fits its transcript split to the engine's own Messages row.
// Pure functions, so tests can hold them without an engine.

import type { Breakdown, Limit, Part } from '../types'

export const CHARS_PER_TOKEN = 3.7

// usage_bars.py's 256-colour palette, as hex.
export const COLORS = {
  system: '#808080', // 244
  rules: '#af87ff', // 141
  skills: '#ff87ff', // 213
  summary: '#87afaf', // 109
  you: '#00afff', // 39
  claude: '#ff8700', // 208
  tools: '#ffd700', // 220
  agents: '#5fd787', // 78
  other: '#5f8787', // 66
  green: '#5fd787', // 78
  yellow: '#ffd700', // 220
  red: '#ff0000', // 196
} as const

/** The kinds usage_bars.py sorts the transcript into, in its order. */
export const KINDS = ['system', 'rules', 'skills', 'summary', 'you', 'claude', 'tools', 'agents', 'other'] as const
export type Kind = (typeof KINDS)[number]

/** Kinds the conversation itself holds: what the engine's Messages row is made of. */
const CONVERSATION: readonly Kind[] = ['summary', 'you', 'claude', 'tools', 'agents', 'skills', 'other']

// Attachment types -> count key. `listing` and `rules` are kept apart from `skills` so the engine's
// own Skills and Memory files rows are not counted twice; with no engine breakdown they fold back
// into usage_bars.py's kinds (listing -> skills).
const ATTACH: Record<string, string> = {
  skill_listing: 'listing',
  invoked_skills: 'skills',
  instructions: 'rules',
  output_style: 'rules',
  output_style_instructions: 'rules',
  queued_command: 'agents',
}
const SKIP_ATTACH = new Set(['prompt_snapshot'])

type Entry = Record<string, unknown>

const size = (x: unknown): number => (typeof x === 'string' ? x.length : (JSON.stringify(x ?? null) ?? '').length)

const add = (counts: Record<string, number>, key: string, n: number) => {
  counts[key] = (counts[key] ?? 0) + n
}

/** Adds one transcript entry's characters to its kind, as usage_bars.py's classify() does. */
export function classify(d: Entry, counts: Record<string, number>): void {
  const t = d.type
  if (t === 'attachment') {
    const a = (d.attachment ?? {}) as Entry
    const at = String(a.type ?? '')
    if (SKIP_ATTACH.has(at)) return
    add(counts, ATTACH[at] ?? 'other', size(a))
    return
  }
  const msg = (d.message ?? {}) as Entry
  const content = msg.content
  if (t === 'user') {
    let kind: string
    if (d.isCompactSummary) {
      kind = 'summary'
    } else if (d.isMeta) {
      const s = typeof content === 'string' ? content : (JSON.stringify(content) ?? '')
      kind = s.includes('Base directory for this skill')
        ? 'skills'
        : s.includes('<agent-message') || s.includes('<task-notification')
          ? 'agents'
          : 'other'
    } else if (Array.isArray(content) && content.some(b => isObj(b) && b.type === 'tool_result')) {
      kind = 'tools'
    } else {
      kind = 'you'
    }
    add(counts, kind, size(content || ''))
  } else if (t === 'assistant' && Array.isArray(content)) {
    for (const b of content) {
      if (!isObj(b)) continue
      if (b.type === 'tool_use') {
        add(counts, 'tools', size(b.input ?? {}))
      } else {
        const text = b.text || b.thinking || ''
        add(counts, 'claude', typeof text === 'string' ? text.length : 0)
      }
    }
  }
}

const isObj = (x: unknown): x is Entry => typeof x === 'object' && x !== null && !Array.isArray(x)

const encoder = new TextEncoder()

/**
 * Reads the whole lines of a chunk of the transcript into `counts` and answers how many bytes they
 * took, so the next read starts after them. A last line with no newline is still being written and
 * is left for next time. A compaction boundary starts the counts over; subagent lines are skipped.
 */
export function scanChunk(text: string, counts: Record<string, number>): number {
  let consumed = 0
  let start = 0
  for (;;) {
    const nl = text.indexOf('\n', start)
    if (nl < 0) break
    const line = text.slice(start, nl)
    consumed += encoder.encode(line).length + 1
    start = nl + 1
    let d: unknown
    try {
      d = JSON.parse(line)
    } catch {
      continue
    }
    if (!isObj(d)) continue
    if (d.type === 'system' && d.subtype === 'compact_boundary') {
      for (const k of Object.keys(counts)) delete counts[k]
      continue
    }
    if (d.isSidechain) continue
    classify(d, counts)
  }
  return consumed
}

const est = (counts: Record<string, number>, key: string) => (counts[key] ?? 0) / CHARS_PER_TOKEN

const part = (key: Kind, tokens: number): Part => ({
  key,
  label: key,
  tokens,
  color: COLORS[key],
  source: 'estimate',
  kind: 'used',
})

/**
 * Splits the engine's Messages row by kind: the transcript estimate's shape, scaled so the kinds add
 * up to exactly the engine's figure. With nothing read yet, the row stays whole.
 */
export function splitMessages(counts: Record<string, number>, messages: number): Part[] {
  const raw = CONVERSATION.map(k => [k, est(counts, k)] as const).filter(([, v]) => v > 0)
  const total = raw.reduce((s, [, v]) => s + v, 0)
  if (total <= 0 || messages <= 0) {
    return messages > 0 ? [{ key: 'messages', label: 'messages', tokens: messages, color: COLORS.other, source: 'engine', kind: 'used' }] : []
  }
  const scale = messages / total
  return raw.map(([k, v]) => part(k, v * scale))
}

/**
 * usage_bars.py's measure(), for when the engine has no breakdown: the transcript estimate fitted
 * to the real used total, the remainder being "system". An estimate that overshoots keeps its shape
 * and leaves a sliver for the system prompt.
 */
export function estimateSplit(counts: Record<string, number>, used: number): Part[] {
  const tokens: Partial<Record<Kind, number>> = {}
  for (const k of KINDS) {
    const v = est(counts, k) + (k === 'skills' ? est(counts, 'listing') : 0)
    if (v > 0) tokens[k] = v
  }
  let sum = Object.values(tokens).reduce((s, v) => s + (v ?? 0), 0)
  if (sum && sum > used * 0.95) {
    const scale = (used * 0.9) / sum
    for (const k of Object.keys(tokens) as Kind[]) tokens[k] = (tokens[k] ?? 0) * scale
    sum = Object.values(tokens).reduce((s, v) => s + (v ?? 0), 0)
  }
  tokens.system = Math.max(used - sum, 0)
  return KINDS.filter(k => (tokens[k] ?? 0) > 0).map(k => part(k, tokens[k] ?? 0))
}

/** An engine /context row, as the engine has it, in usage_bars.py's colours where it is one of its kinds. */
export type EngineRow = { name: string; tokens: number; color: string; kind: 'used' | 'free' | 'buffer' | 'deferred' }

// Engine rows -> usage_bars.py kinds, by the label /context prints. The engine's own theme colour
// stands for any row not listed here.
const ROWS: [RegExp, string, string][] = [
  [/^system prompt/i, 'system', COLORS.system],
  [/^system tools/i, 'system tools', '#949494'],
  [/^mcp/i, 'mcp tools', '#6c6c6c'],
  [/agent/i, 'custom agents', '#5faf87'],
  [/memory/i, 'rules', COLORS.rules],
  [/skill/i, 'skill listing', COLORS.skills],
]

/** Builds the breakdown from the engine's /context rows, splitting its Messages row by the transcript. */
export function fromEngine(
  rows: readonly EngineRow[],
  counts: Record<string, number>,
  window: number,
  autoCompactAt: number | null,
): Breakdown {
  const parts: Part[] = []
  for (const row of rows) {
    if (row.kind === 'deferred' || row.tokens <= 0) continue
    if (row.kind === 'used' && /message/i.test(row.name)) {
      parts.push(...splitMessages(counts, row.tokens))
      continue
    }
    const hit = ROWS.find(([re]) => re.test(row.name))
    parts.push({
      key: row.name,
      label: row.kind === 'used' ? (hit?.[1] ?? row.name.toLowerCase()) : row.name.toLowerCase(),
      tokens: row.tokens,
      color: row.kind === 'used' ? (hit?.[2] ?? row.color) : 'inactive',
      source: 'engine',
      kind: row.kind,
    })
  }
  const used = parts.filter(p => p.kind === 'used').reduce((s, p) => s + p.tokens, 0)
  return { parts, used, window, autoCompactAt, basis: 'engine' }
}

/** The breakdown with no engine rows: usage_bars.py's split of the real used total. */
export function fromEstimate(counts: Record<string, number>, used: number, window: number): Breakdown {
  return { parts: estimateSplit(counts, used), used, window, autoCompactAt: null, basis: 'estimate' }
}

// ---- percent maths ----

export const clampPct = (p: number) => Math.max(0, Math.min(100, Number.isFinite(p) ? p : 0))

/** `part` over `whole` as a percentage; 0 for an empty whole. */
export const percentOf = (part: number, whole: number) => (whole > 0 ? (part / whole) * 100 : 0)

/** A kind's share of the used part, as usage_bars.py prints it: whole percent, never under 1. */
export const share = (tokens: number, used: number) => Math.max(1, Math.round(percentOf(tokens, used)))

/** Filled cells of a `width`-cell bar at `pct`. */
export const filled = (pct: number, width: number) => Math.round((clampPct(pct) / 100) * width)

/**
 * Cells per value, rounded by largest remainder so they add up to exactly `round(sum / scaleTo *
 * width)` (never past `width`): usage_bars.py's segments().
 */
export function cells(values: readonly number[], scaleTo: number, width: number): number[] {
  if (scaleTo <= 0 || width <= 0) return values.map(() => 0)
  const exact = values.map(v => (Math.max(0, v) / scaleTo) * width)
  const want = Math.min(width, Math.round(values.reduce((s, v) => s + Math.max(0, v), 0) / scaleTo * width))
  const whole = exact.map(Math.floor)
  const order = exact.map((c, i) => i).sort((a, b) => exact[b]! - whole[b]! - (exact[a]! - whole[a]!))
  let missing = want - whole.reduce((s, n) => s + n, 0)
  for (const i of order) {
    if (missing <= 0) break
    whole[i]! += 1
    missing -= 1
  }
  return whole
}

/** usage_bars.py's colour for a fill: green under 50, yellow under 80, red past it. */
export const pctColor = (p: number) => (p < 50 ? COLORS.green : p < 80 ? COLORS.yellow : COLORS.red)

// ---- words ----

export function short(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1000) return `${Math.round(n / 1000)}k`
  return String(Math.trunc(n))
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

/** Time until a reset, as usage_bars.py's until(): `2h05m`, `40m`, `now`, or past a day `Fri 9am`. */
export function until(resetsAt: string | undefined, now: number): string {
  if (!resetsAt) return ''
  const at = Date.parse(resetsAt)
  if (Number.isNaN(at)) return ''
  const s = (at - now) / 1000
  if (s <= 0) return 'now'
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  if (h >= 24) {
    const d = new Date(at)
    const hr = d.getHours()
    return `${DAYS[d.getDay()]} ${hr % 12 || 12}${hr < 12 ? 'am' : 'pm'}`
  }
  return h ? `${h}h${String(m).padStart(2, '0')}m` : `${m}m`
}

/** Session clock, as ccstatusline's: `1h07m`, `12m`. */
export function elapsed(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 60_000))
  const h = Math.floor(total / 60)
  const m = total % 60
  return h ? `${h}h${String(m).padStart(2, '0')}m` : `${m}m`
}

export const money = (usd: number | null) => (usd === null ? 'n/a' : `$${usd.toFixed(2)}`)

/** The two plan windows the CLI shows, by the engine's kind; undefined where it has no reading. */
export function planWindows(limits: readonly Limit[]): { label: string; limit: Limit | undefined }[] {
  return [
    { label: '5h', limit: limits.find(l => l.kind === 'five_hour') },
    { label: 'wk', limit: limits.find(l => l.kind === 'seven_day') },
  ]
}

/** `git diff --shortstat` -> lines added and removed. */
export function parseShortstat(out: string): { added: number; removed: number } {
  const added = /(\d+) insertion/.exec(out)
  const removed = /(\d+) deletion/.exec(out)
  return { added: added ? Number(added[1]) : 0, removed: removed ? Number(removed[1]) : 0 }
}

