import type { ElementTable } from 'claude-code'

import type { Breakdown, Git, Part, Snapshot } from '../types'
import { cells, COLORS, elapsed, filled, money, pctColor, percentOf, planWindows, share, short, until } from './meter'

export type El = Pick<ElementTable, 'Box' | 'Text' | 'Button'>

export const MUTED = '#a8a8a8'
const FREE = 'inactive'

export type Data = {
  snap: Snapshot | null
  git: Git | null
  breakdown: Breakdown | null
  now: number
  columns: number
}

/** A bar of `width` cells at `pct`, in the fill's colour. */
function PctBar(el: El, pct: number, width: number) {
  const { Text } = el
  const n = filled(pct, width)
  return (
    <Text>
      <Text color={pctColor(pct)}>{'█'.repeat(n)}</Text>
      <Text color={FREE}>{'░'.repeat(width - n)}</Text>
    </Text>
  )
}

/** A bar of `width` cells, a colour per used part, scaled to `scaleTo` tokens: usage_bars.py's segments(). */
function KindBar(el: El, parts: readonly Part[], scaleTo: number, width: number) {
  const { Text } = el
  const used = parts.filter(p => p.kind === 'used')
  const n = cells(
    used.map(p => p.tokens),
    scaleTo,
    width,
  )
  const rest = width - n.reduce((s, c) => s + c, 0)
  return (
    <Text>
      {used.map((p, i) => (n[i] ? <Text color={p.color}>{'█'.repeat(n[i]!)}</Text> : null))}
      <Text color={FREE}>{'░'.repeat(Math.max(0, rest))}</Text>
    </Text>
  )
}

/**
 * The token count a window bar of the breakdown is scaled to, so its fill matches the engine's
 * percent beside it: the breakdown's parts may add up to a little more or less than the engine's
 * live figure, and measure against the compaction window rather than the model's.
 */
export const kindScale = (b: Breakdown, snap: Snapshot) => (snap.tokens ? (b.used * snap.window) / snap.tokens : b.window)

const Sep = (el: El) => <el.Text color={MUTED}> │ </el.Text>

/** The CLI's line 1, essentials first: model, context %, plan limits, cost, branch. Wider bands add bars, resets, changes and the clock. */
export function Band(el: El, d: Data, onOpen: () => void) {
  const { Box, Text, Button } = el
  const { snap, git, breakdown, now, columns } = d
  const wide = columns >= 120
  const mid = columns >= 90
  const pct = snap?.percent

  const items = [
    <Text color="cyan">{snap?.model ?? '…'}</Text>,
    <Text>
      ctx{' '}
      {wide && breakdown && snap
        ? [KindBar(el, breakdown.parts, kindScale(breakdown, snap), 12), ' ']
        : mid && pct !== undefined
          ? [PctBar(el, pct, 8), ' ']
          : null}
      {pct === undefined ? <Text color={MUTED}>–</Text> : <Text color={pctColor(pct)}>{pct}%</Text>}
      {wide && snap?.tokens !== undefined ? <Text color={MUTED}> {short(snap.tokens)}/{short(snap.window)}</Text> : null}
    </Text>,
    ...planWindows(snap?.limits ?? []).map(({ label, limit }) =>
      limit === undefined ? (
        <Text color={MUTED}>{label} n/a</Text>
      ) : (
        <Text>
          {label} {mid ? [PctBar(el, limit.percentUsed, 6), ' '] : null}
          <Text color={pctColor(limit.percentUsed)}>{Math.round(limit.percentUsed)}%</Text>
          {mid && limit.resetsAt ? <Text color={MUTED}> ↻{until(limit.resetsAt, now)}</Text> : null}
        </Text>
      ),
    ),
    <Text color={snap?.costUsd == null ? MUTED : undefined}>{snap ? money(snap.costUsd) : '$ n/a'}</Text>,
    git ? (
      <Text>
        <Text color="magenta">⎇ {git.branch}</Text>
        {wide && git.worktree ? <Text color={MUTED}> ({git.worktree})</Text> : null}
        {mid && (git.added || git.removed) ? (
          <Text color="yellow">
            {' '}
            +{git.added} −{git.removed}
          </Text>
        ) : null}
      </Text>
    ) : null,
    wide && snap ? <Text color={MUTED}>{elapsed(now - snap.startedAt)}</Text> : null,
  ].filter(x => x !== null)

  return (
    <Box flexDirection="row" flexWrap="wrap" justifyContent="space-between">
      <Text wrap="truncate-end">{items.flatMap((x, i) => (i ? [Sep(el), x] : [x]))}</Text>
      <Button key="open" label="usage" plain onPress={onOpen} />
    </Box>
  )
}

/** The full context breakdown, plan limits and git: what /usage opens. */
export function Pane(el: El, d: Data, onRefresh: () => void) {
  const { Box, Text, Button } = el
  const { snap, git, breakdown, now, columns } = d
  const barWidth = Math.max(10, Math.min(60, columns - 24))

  const header = (
    <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
      <Text bold color="cyan">
        {snap?.model ?? '…'}
      </Text>
      <Text>
        cost <Text color={snap?.costUsd == null ? MUTED : undefined}>{snap ? money(snap.costUsd) : 'n/a'}</Text>
      </Text>
      {snap ? <Text color={MUTED}>session {elapsed(now - snap.startedAt)}</Text> : null}
      <Button key="refresh" label="refresh" plain onPress={onRefresh} />
    </Box>
  )

  const limits = (
    <Box flexDirection="column">
      <Text bold>Plan limits</Text>
      {planWindows(snap?.limits ?? []).map(({ label, limit }) => (
        <Box flexDirection="row" columnGap={1}>
          <Box width={3}>
            <Text>{label}</Text>
          </Box>
          {limit === undefined ? (
            <Text color={MUTED}>n/a (the engine has no reading for this window)</Text>
          ) : (
            <Text>
              {PctBar(el, limit.percentUsed, 20)} <Text color={pctColor(limit.percentUsed)}>{limit.percentUsed.toFixed(0)}%</Text>
              {limit.resetsAt ? <Text color={MUTED}> resets in {until(limit.resetsAt, now)}</Text> : null}
            </Text>
          )}
        </Box>
      ))}
    </Box>
  )

  const context = snap ? (
    <Box flexDirection="column">
      <Text bold>Context</Text>
      <Text>
        {breakdown ? KindBar(el, breakdown.parts, kindScale(breakdown, snap), barWidth) : PctBar(el, snap.percent ?? 0, barWidth)}{' '}
        {snap.tokens === undefined ? (
          <Text color={MUTED}>no response yet</Text>
        ) : (
          <Text>
            {short(snap.tokens)}/{short(snap.window)} <Text color={pctColor(snap.percent ?? 0)}>{snap.percent ?? 0}%</Text>
          </Text>
        )}
      </Text>
    </Box>
  ) : (
    <Text color={MUTED}>Waiting for the engine's first measurement.</Text>
  )

  return (
    <Box flexDirection="column" rowGap={1}>
      {header}
      {limits}
      {context}
      {breakdown ? Breakdown_(el, breakdown, barWidth) : null}
      {git ? (
        <Text>
          <Text color="magenta">⎇ {git.branch}</Text>
          {git.worktree ? <Text color={MUTED}> · worktree {git.worktree}</Text> : null}
          <Text color="yellow">
            {' '}
            · +{git.added} −{git.removed}
          </Text>
        </Text>
      ) : null}
    </Box>
  )
}

function Breakdown_(el: El, b: Breakdown, barWidth: number) {
  const { Box, Text } = el
  const used = b.parts.filter(p => p.kind === 'used')
  const other = b.parts.filter(p => p.kind !== 'used')
  const hasEstimate = b.parts.some(p => p.source === 'estimate')

  const row = (p: Part) => (
    <Box flexDirection="row" columnGap={1}>
      <Text color={p.kind === 'used' ? p.color : FREE}>■</Text>
      <Box width={16}>
        <Text color={p.kind === 'used' ? undefined : MUTED} wrap="truncate-end">
          {p.label}
        </Text>
      </Box>
      <Box width={7}>
        <Text>{short(p.tokens)}</Text>
      </Box>
      <Box width={5}>
        <Text color={MUTED}>{p.kind === 'used' ? `${share(p.tokens, b.used)}%` : `${Math.round(percentOf(p.tokens, b.window))}%`}</Text>
      </Box>
      {p.source === 'estimate' ? <Text color={MUTED}>est.</Text> : null}
    </Box>
  )

  return (
    <Box flexDirection="column">
      <Text bold>Breakdown of the used part</Text>
      <Text>
        {KindBar(el, used, b.used, barWidth)} {short(b.used)}
      </Text>
      {used.map(row)}
      {other.length ? <Text color={MUTED}>of the {short(b.window)} window:</Text> : null}
      {other.map(row)}
      {b.autoCompactAt ? <Text color={MUTED}>auto-compacts at {short(b.autoCompactAt)}</Text> : null}
      <Text color={MUTED} wrap="wrap">
        {b.basis === 'engine'
          ? `Rows are the engine's /context counts (its own local estimate). ${hasEstimate ? 'Rows marked est. split its Messages row by kind from the transcript (3.7 chars a token), scaled to that row.' : ''}`
          : 'Estimate: the engine gave no breakdown, so this is usage_bars.py\'s split of the real used total (transcript at 3.7 chars a token, the rest as system).'}
      </Text>
    </Box>
  )
}

