/** One plan-limit window as the engine reports it (`$.session.usage().rateLimits`). */
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

/** The line-1 figures. Everything here is the engine's own value, or absent / null when it has none. */
export type Snapshot = {
  model: string
  /** Input tokens the last response was answered over; absent before the first response. */
  tokens?: number
  /** The model's context window in tokens. */
  window: number
  /** tokens / window as a whole percentage; absent before the first response. */
  percent?: number
  /** Empty when the engine has no reading (off a subscription, or before the first response). */
  limits: Limit[]
  /** US dollars; null where the host keeps no cost ledger. */
  costUsd: number | null
  /** When the session began, epoch ms. */
  startedAt: number
  measuredAt: number
}

export type Git = {
  branch: string
  /** The linked worktree's folder name; null in the main working tree. */
  worktree: string | null
  added: number
  removed: number
}

/** One row of the context breakdown, in tokens. */
export type Part = {
  key: string
  label: string
  tokens: number
  /** Hex colour, from usage_bars.py's palette where the kind is one of its kinds. */
  color: string
  /** engine: the engine's /context row. estimate: the transcript split, fitted to the engine's Messages row (or, with no breakdown, to the used total). */
  source: 'engine' | 'estimate'
  /** used content, or the window left / the compaction reserve, which the used bar leaves out. */
  kind: 'used' | 'free' | 'buffer'
}

export type Breakdown = {
  parts: Part[]
  /** Used tokens the parts add up to. */
  used: number
  /** The window the engine's breakdown measures against (the compaction window when one is set). */
  window: number
  autoCompactAt: number | null
  /** engine: the engine's /context breakdown was available. estimate: it was not, and the split is usage_bars.py's alone. */
  basis: 'engine' | 'estimate'
}

/** Characters per kind read from the transcript since the last compaction, cached by file size. */
export type Scan = { path: string; offset: number; counts: Record<string, number> }

declare module 'claude-code' {
  interface PluginState {
    'usage-meter': {
      snap: Snapshot | null
      git: Git | null
      breakdown: Breakdown | null
      scan: Scan | null
      transcript: string | null
    }
  }
}
